tableData:
{{
  (function() {
    const data = Get_Liste_Devis.data || [];
    let groupedData = [];
    let counts = {};

    // 1. On compte combien on a de devis par statut
    data.forEach(row => {
      let st = row.Statut || "Non défini";
      counts[st] = (counts[st] || 0) + 1;
    });

    let currentStatut = null;

    // 2. On reconstruit la liste en insérant des "fausses lignes" de titre
    data.forEach((row) => {
      let st = row.Statut || "Non défini";

      // Dès qu'on change de statut, on insère une ligne de titre
      if (st !== currentStatut) {
        groupedData.push({
          Client_Affichage: st + " (" + counts[st] + ")", 
          isHeader: true // On marque cette ligne pour pouvoir la colorer
        });
        currentStatut = st;
      }

      // Puis on insère la vraie ligne de devis
      groupedData.push(row);
    });

    return groupedData;
  })()
}}
